package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1n9y62agq998jt8w59az60xcqlftjknjg2grhn4"), 0),
		},
		"Remove validator g1n9y62agq998jt8w59az60xcqlftjknjg2grhn4",
		"Remove operator g1n9y62agq998jt8w59az60xcqlftjknjg2grhn4 from the active valset.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}
